window.NOTE_DEMOS={"y2020q44":{"kind":"choose","title":"把选中正文排成两栏","task":"点击功能，观察它是否真正改变文档版面。","options":[{"label":"布局→分栏→两栏","result":"正确。文字会按栏连续流动，局部应用时Word会建立节边界。","tone":"good"},{"label":"视图→并排查看","result":"只把两个窗口并排显示，不改变文档。","tone":"bad"},{"label":"插入两列表格","result":"能形成两块区域，但不等于报刊式分栏。","tone":"warn"},{"label":"连续按Tab","result":"只是插入制表位置，无法形成连续栏。","tone":"bad"}]},"y2024q66":{"kind":"explore","title":"拨动行距，救出被裁切的图片","task":"切换段落行距，直接观察嵌入型图片的可见高度。","initial":"图片高度72磅，当前段落使用固定值20磅。","actions":[{"label":"固定值20磅","stage":"图片被裁切","result":"行框被锁死，容不下图片。","tone":"bad"},{"label":"固定值80磅","stage":"完整但僵硬","result":"能显示完整，换图后仍可能不合适。","tone":"warn"},{"label":"最小值20磅","stage":"内容高时自动扩展","result":"既保留最低行距，又允许图片撑高。","tone":"good"},{"label":"单倍行距","stage":"随行内对象扩展","result":"通常可完整容纳嵌入型图片。","tone":"good"}]},"y2020q60":{"kind":"sequence","title":"给整张表添加所有框线","task":"按最直接的Word表格操作顺序点击。","steps":[{"label":"选中整张表格","detail":"左上角移动手柄可快速选中整表。"},{"label":"进入表格工具“设计”","detail":"找到边框相关设置。"},{"label":"打开“边框”菜单","detail":"确认应用范围是当前所选表格。"},{"label":"选择“所有框线”","detail":"内部和外部框线一次完成。"}]},"y2020q62":{"kind":"sequence","title":"让跨页表格重复标题","task":"按Word 2016正确步骤点击。","steps":[{"label":"选中表格最前面的标题行","detail":"可以选择连续的多行标题。"},{"label":"进入表格工具“布局”","detail":"该选项只在表格被选中时出现。"},{"label":"点击“重复标题行”","detail":"表格自然跨页时，各页顶部重复标题。"}]},"y2024q55":{"kind":"sequence","title":"把动态页码放进现有形状","task":"在页眉里辨认“选中形状”和“编辑形状文字”，再插入PAGE域。","steps":[{"label":"进入页眉并选中平行四边形","detail":"先确认操作对象位于页眉层。"},{"label":"再次单击形状内部放置光标","detail":"外框选择变为文字插入状态。"},{"label":"页码→当前位置","detail":"把动态页码插在当前光标位置。"},{"label":"选择简洁页码样式","detail":"形状内出现PAGE域结果。"},{"label":"关闭页眉检查多页结果","detail":"每页形状内显示各自的页码。"}]}};
window.NOTE_NAVIGATION={"merged-5":{"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"导航和自动目录依赖真实标题样式；需要统一外观时应修改对应样式定义。","chapter":3},{"id":"y2022q72","label":"Word标题层级决定导入PowerPoint后的幻灯片结构","reason":"同一套Word标题层级还决定从大纲导入PowerPoint时的幻灯片和正文归属。","chapter":5},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"普通目录依据标题，图表目录依据题注，可对照理解自动目录各自的结构来源。","chapter":3}],"topics":[]},"y2022q10":{"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"按样式选中可以批量删文字；只要统一标题格式时应修改样式定义并保留内容。","chapter":3},{"id":"y2025q48","label":"查找替换可批量处理文本、特殊字符与格式","reason":"查找替换也能按格式匹配，但要核对查找条件，防止相同外观掩盖不同样式。","chapter":3}],"topics":[]},"y2023q55":{"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"正文下划线属于字符格式会打印，校对波浪线只提示可能的问题。","chapter":3},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"隐藏校对提示与隐藏修订都只影响查看；原文是否改正或修订是否处理需另外判断。","chapter":3}],"topics":[]},"y2024q7":{"related":[{"id":"y2022q10","label":"按同一格式或样式批量选中文本","reason":"连续键盘选区与按样式跨位置选区服务不同批量任务，先确认目标范围再删除或改格式。","chapter":3}],"topics":[]},"y2025q48":{"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"替换匹配格式不等于修改样式定义；要让以后同级标题也继承规则，应改样式。","chapter":3},{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"清理连续空段前先认清段落标记与手动换行，避免替换错结构。","chapter":3},{"id":"y2024q57","label":"用-*通配符批量删除连字符及其后缀","reason":"Excel和Word的通配符入口及语法不同，跨软件操作不能照搬勾选步骤。","chapter":4}],"topics":[]},"merged-8":{"related":[{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"编号错位常要调整文本缩进和制表位，先认清首行、悬挂与整段缩进。","chapter":3},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"章节多级编号应与标题层级协调，单纯增大缩进不会建立可导航的标题结构。","chapter":3}],"topics":[]},"y2020q41":{"related":[{"id":"y2020q61","label":"只改变一页纸张方向","reason":"不同页眉的范围由节划定；分页符只换页，不能建立独立页眉设置范围。","chapter":3},{"id":"y2024q55","label":"在形状中放置光标后插入PAGE域","reason":"页码用PAGE域保持动态，但在哪一节显示及如何起号还要检查链接与编号设置。","chapter":3},{"id":"y2024q54","label":"页眉横线应作为段落下边框设置","reason":"页眉横线通常是段落边框，删页眉文字后仍有横线时应检查它。","chapter":3}],"topics":[{"id":"cmp-word-format-scope","title":"Word格式：字、段、节和查看范围"}]},"merged-7":{"related":[{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"段落末行的对齐效果取决于段落结构，Enter与手动换行不能混用。","chapter":3},{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"居中后仍有偏移时，应继续检查首行、悬挂和左右缩进标记。","chapter":3},{"id":"y2025q2","label":"字符编码、汉字机内码、字形与全角半角要分清","reason":"全角半角转换改变字符身份，不能把它当成只改变字号或字体的操作。","chapter":1}],"topics":[{"id":"cmp-word-format-scope","title":"Word格式：字、段、节和查看范围"}]},"y2020q43":{"related":[{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"首行、悬挂和整段左缩进可用标尺分别调节，先按受影响的行确定标记。","chapter":3},{"id":"y2025q48","label":"查找替换可批量处理文本、特殊字符与格式","reason":"替换空段要识别真正的段落标记；手动换行与含空格的空行不等于连续空段。","chapter":3}],"topics":[{"id":"cmp-word-format-scope","title":"Word格式：字、段、节和查看范围"}]},"y2020q44":{"related":[{"id":"y2020q61","label":"只改变一页纸张方向","reason":"局部分栏与局部横向都要核对应用范围及分节边界，避免版式影响后文。","chapter":3},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"Web版式、多页查看等属于视图选择，不能代替会影响打印的正文分栏。","chapter":3}],"topics":[{"id":"cmp-word-format-scope","title":"Word格式：字、段、节和查看范围"}]},"y2020q61":{"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"分节能隔离纸张方向，但页眉页脚是否继承还需单独检查链接状态。","chapter":3},{"id":"y2020q44","label":"正文分栏会改变排版，页面并排只改变屏幕查看","reason":"局部分栏可使用连续分节，局部横向常用下一页分节；二者都需核对影响范围。","chapter":3},{"id":"y2025q10","label":"PowerPoint的节用于组织，导航最终定位幻灯片","reason":"Word的节可控制页面方向，PowerPoint的节主要组织幻灯片，不能套用相同能力。","chapter":5}],"topics":[{"id":"cmp-word-format-scope","title":"Word格式：字、段、节和查看范围"},{"id":"cmp-ppt-object-slide-deck","title":"PowerPoint：对象、页面、节、母版与全稿"}]},"y2021q56":{"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"先在单份文档建立可统一修改的样式，再把样式保存进模板供新文档使用。","chapter":3},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"把标题样式写入模板，既统一外观，也为导航、自动目录提供结构。","chapter":3}],"topics":[]},"y2022q24":{"related":[{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"观察第一行和其余行的位置，才能区分首行缩进与悬挂缩进。","chapter":3},{"id":"merged-8","label":"项目符号、编号与多级列表","reason":"多级列表的编号位置、文本缩进与制表位要协调，不能只拖一个标记或堆空格。","chapter":3}],"topics":[]},"y2022q70":{"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"普通背景图片需要设置文字环绕和锚定关系；衬于文字下方不会天然重复到每页。","chapter":3}],"topics":[]},"y2023q52":{"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"只有真正使用标题样式或大纲级别的段落才形成可靠导航和目录结构。","chapter":3},{"id":"y2021q56","label":"样式统一一份文档，模板给多份文档共同起点","reason":"当前文档样式规则确定后，可保存进模板；修改当前文档不自动更新所有旧文件。","chapter":3},{"id":"y2022q10","label":"按同一格式或样式批量选中文本","reason":"想删所有某样式文字时要选中实例，修改或删除样式定义不是删除这些内容。","chapter":3}],"topics":[]},"y2024q54":{"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"先进入正确节和正确类型的页眉，再设边框，避免因链接状态影响其他节。","chapter":3},{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"页眉横线也可通过页眉样式统一修改，直接格式可能覆盖样式规则。","chapter":3},{"id":"y2020q60","label":"给表格设置全部框线","reason":"边框都需核对应用对象：页眉段落与整张表格的范围不同。","chapter":3}],"topics":[]},"y2024q66":{"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"嵌入型图片按文本行排布，因此可能被固定行高裁切；浮动图片采用另一套位置规则。","chapter":3},{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"图像被裁切不一定要缩小原图，应先分辨是行距限制还是主动裁剪。","chapter":3}],"topics":[]},"y2026q47":{"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"自动字符间距、字形字号与段落对齐作用不同，调整版面前应先确认要改变哪一层。","chapter":3},{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"真实空格属于文本内容，缩进和自动间距属于排版规则，不能用删除空格替代所有调整。","chapter":3}],"topics":[]},"y2020q60":{"related":[{"id":"y2020q63","label":"整张表格居中与单元格内容居中","reason":"设置前先确定选中的是表格对象还是格内文字；整表边框和格内对齐作用范围不同。","chapter":3},{"id":"y2024q54","label":"页眉横线应作为段落下边框设置","reason":"边框设置都要核对“应用于”，页眉段落下边框不能用页面或表格边框替代。","chapter":3}],"topics":[]},"y2020q62":{"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"重复标题行应在打印布局核对，屏幕查看方式会影响是否看得到分页效果。","chapter":3},{"id":"y2024q58","label":"选中第3行后冻结可保持前两行可见","reason":"Word重复表头用于跨页打印；Excel冻结窗格只用于滚动查看，两者用途容易混淆。","chapter":4}],"topics":[]},"y2020q63":{"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"开始选项卡的段落居中只移动文字，先理解段落格式才能与整表对象居中区分。","chapter":3},{"id":"y2020q60","label":"给表格设置全部框线","reason":"表格格式操作依赖选区与应用范围，整表和所选单元格不能混为一谈。","chapter":3}],"topics":[]},"y2022q69":{"related":[{"id":"y2021q9","label":"跨工作簿引用要指明工作簿和工作表","reason":"跨文件链接都依赖源位置和更新状态，看到旧缓存值不能证明源文件已同步。","chapter":4},{"id":"merged-12","label":"保留图表结构才能按系列或类别动画","reason":"保留链接关系、可编辑对象结构和源格式是不同选择，也影响PowerPoint图表的更新与动画。","chapter":5}],"topics":[{"id":"cmp-copy-move-link","title":"复制、移动、快捷方式、链接与嵌入"}]},"y2024q8":{"related":[{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"Word表格公式与题注、交叉引用同样使用域，源内容改变后要核对并更新域。","chapter":3},{"id":"y2024q10","label":"清除内容只移除值或公式，不清除格式","reason":"Word表格和Excel单元格的Delete通常清空内容，删除结构需使用对应删除操作。","chapter":4},{"id":"y2021q47","label":"导入CSV时明确分隔符和列类型，保住长编号","reason":"文本转表格和CSV导入都要先确认分隔符与字段结构，不能只按视觉间距判断列。","chapter":4}],"topics":[{"id":"cmp-delete-context","title":"同一个Delete，作用对象可能完全不同"}]},"merged-9":{"related":[{"id":"y2024q66","label":"固定行距过小会裁切嵌入型图片","reason":"图片看起来缺一块可能来自固定行距裁切，应先排除排版原因再改图像尺寸。","chapter":3},{"id":"y2026q53","label":"更改图片可保留对象的大部分效果","reason":"替换图片后要重新检查纵横比和裁剪，保留对象效果不保证新图片构图合适。","chapter":5}],"topics":[]},"y2022q54":{"related":[{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"艺术字可与图片、形状组合，但要选对象外框，不能停留在文字编辑状态。","chapter":3},{"id":"y2024q26","label":"艺术字是可旋转、填充和组合的图形对象","reason":"PowerPoint艺术字同样保留文字填充、旋转与组内编辑能力，可迁移对象选择思路。","chapter":5}],"topics":[]},"y2023q7":{"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"字符上下标只改选中文字位置；分数、根式等复杂结构应使用内置公式对象。","chapter":3},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"需要给公式编号并在正文引用时，应使用题注和交叉引用保持对应关系。","chapter":3}],"topics":[]},"y2025q47":{"related":[{"id":"y2024q66","label":"固定行距过小会裁切嵌入型图片","reason":"嵌入型图片占文本行，若显示不全应检查段落固定行距。","chapter":3},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"组合多个对象前，嵌入型图片通常须先改成可共同选择的非嵌入型对象。","chapter":3},{"id":"y2025q56","label":"对象叠放顺序决定箭头是否被形状遮挡","reason":"文字环绕管对象与正文的关系，两个浮动对象谁遮挡谁则由叠放顺序控制。","chapter":3}],"topics":[]},"y2025q56":{"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"改变对象与正文的环绕关系，不能代替两个浮动形状之间的层级调整。","chapter":3},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"对象组合后仍可进入组内选择和编辑，必要时先定位被遮挡的成员。","chapter":3}],"topics":[]},"y2026q36":{"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"嵌入型图片按字符排布，组合前需理解并调整它的环绕方式。","chapter":3},{"id":"y2025q56","label":"对象叠放顺序决定箭头是否被形状遮挡","reason":"组合管理整体操作，叠放顺序管理前后遮挡；组合本身不会自动修正可见关系。","chapter":3}],"topics":[]},"y2022q71":{"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"Word区域限制编辑与文件属性、目录权限属于不同层级，不能用只读属性替代正文例外。","chapter":2},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"限制编辑决定能否修改，修订决定如何记录与处理修改，两者解决不同协作问题。","chapter":3}],"topics":[]},"merged-6":{"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"自动目录依赖标题，图表目录依赖题注；先建立结构再生成目录，手输编号不够。","chapter":3},{"id":"y2024q8","label":"Word表格的转换、计算、排序与删除","reason":"Word表格公式也是域，可与题注引用一起理解源内容变化后的更新操作。","chapter":3},{"id":"y2022q55","label":"脚注在页底，尾注通常在文末或节末","reason":"题注给图表编号，脚注补充说明，先按用途选择对象再插入引用。","chapter":3}],"topics":[]},"y2022q55":{"related":[{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"脚注引用连接说明，交叉引用连接题注目标，均应管理引用关系而非手工写显示编号。","chapter":3},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"脚注属于正文的补充说明，批注用于审阅交流，二者在交付文本中的角色不同。","chapter":3}],"topics":[]},"y2023q56":{"related":[{"id":"y2022q71","label":"只锁表格、保留正文可编辑，需要设置编辑例外","reason":"开启修订不等于限制修改权限，若需正文可改而表格受保护，还要设置编辑例外。","chapter":3},{"id":"y2023q55","label":"校对波浪线提示可能的问题，不属于打印正文","reason":"编辑提示和审阅标记均可被隐藏，但隐藏不意味着错误已改正或修订已接受。","chapter":3}],"topics":[]},"y2024q55":{"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"PAGE域显示的页码仍受当前节的起号、页眉页脚类型及链接状态影响。","chapter":3},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"自动页码、题注和交叉引用都由域生成动态内容，不能用手输数字替代。","chapter":3}],"topics":[]},"y2025q36":{"related":[{"id":"y2021q47","label":"导入CSV时明确分隔符和列类型，保住长编号","reason":"收件人表中的长编号须在导入时保留文本类型，精度丢失后邮件合并不能还原。","chapter":4},{"id":"y2021q50","label":"先提取一位，再判奇偶，最后选择输出","reason":"“如果…那么…否则”与IF同样按条件选择输出，字段值和真、假分支需逐项核对。","chapter":4},{"id":"y2024q59","label":"格式化为表格同时建立结构化数据区域","reason":"Excel来源需规范列标题与明细记录，建表时核对标题行，可减少姓名等合并字段识别错误。","chapter":4}],"topics":[]}};
